// 꿈해몽 v3 — 꿈 하나 = 긴 기사. 상세 해몽 + 상황별 풀이(무제한 확장) + 분야별 영향 + 심리 + 조언.
// SEO 롱테일·체류시간 핵심. ⚠️ 당첨 보장/예측 아님. 전통 해몽 + 심리 + 재미.
import { hashString, pickUnique } from "./seed.js";
import { meaningOf, LOTTO_PICK, LOTTO_MAX, type LuckyNumbers } from "./lotto.js";

export type DreamCategory = "재물" | "길몽" | "애정" | "변화" | "주의";
export type DreamLuck = "대길" | "길몽" | "중립" | "주의" | "흉몽";

export interface DreamCase {
  label: string; // 상황 (예: "검은 돼지를 봤다")
  luck: DreamLuck;
  text: string; // 풀이
}
export interface DreamCaseGroup {
  group: string; // 묶음 제목 (예: "색깔·종류별")
  cases: DreamCase[];
}
export interface DreamField {
  label: string; // 재물운/애정운/건강운/직장운/대인운
  text: string;
}
export interface Dream {
  id: string;
  keyword: string;
  emoji: string;
  category: DreamCategory;
  luck: DreamLuck;
  meaning: string; // 한 줄 요약(훅)
  overview: string[]; // 상세 해몽(여러 문단)
  situations: DreamCaseGroup[]; // 상황별 풀이(다수)
  fields: DreamField[]; // 분야별 영향
  psych: string; // 심리 해석
  advice: string; // 행동 조언·정리
  folk?: string; // 전통 속설·유래(재미)
  aliases: string[]; // 검색 별칭(롱테일)
  related: string[]; // 관련 꿈 id
}

const L = (label: string, luck: DreamLuck, text: string): DreamCase => ({ label, luck, text });

