    advice: "주신 게 있으면 길몽으로 기뻐하고, 표정이 어두웠다면 건강을 한 번 챙겨보세요. 말씀을 들었다면 잊지 말고 메모해두면 좋아요.",
    folk: "예부터 조상 꿈은 '헛꿈이 없다'고 하여, 좋은 말씀을 들으면 새겨듣고 무언가를 받으면 그날 복권을 사기도 했어요.",
