    psych: "마음 깊은 곳의 잠재력과 감정의 크기, 더 큰 세계로 나아가고 싶은 바람을 비춰요.",
    advice: "잔잔하면 안정 전략을, 파도가 크면 변화를 준비하세요. 건지거나 건넌 꿈이면 적극적으로 나아가도 좋아요.",
    folk: "예부터 바닷물이 맑고 가득한 꿈은 재물이 넘친다고 반겼고, 바다가 갈라지는 꿈은 큰 뜻을 이룬다고 했어요.",
    aliases: ["바다", "파도", "해변", "큰물", "해일", "항해", "일출"], related: ["water", "fish", "rain"],
