    psych: "오래가는 안정·복에 대한 바람, 조급함 없이 끝내 이루려는 끈기가 거북이의 모습으로 떠오른 거예요.",
    advice: "집에 들거나 품은 꿈이면 안정된 재물운이 좋아요. 더디게 다가오는 꿈이면 조급해 말고 기다리세요.",
    folk: "예부터 거북이·자라가 집에 드는 꿈은 큰 재물과 장수가 든다고 하여 으뜸 길몽으로 귀하게 여겼어요.",
    aliases: ["거북이", "자라", "황금거북이", "거북이타는"], related: ["dragon", "fish", "snake"],
