    advice: "떠오르거나 품는 해면 큰 도전·승부에 더없이 좋은 기운이에요. 지는 해면 잠시 힘을 비축하세요.",
    folk: "예부터 해를 품거나 삼키는 꿈은 임금·큰 인물이 날 태몽이라 하여 으뜸 길몽으로 귀하게 여겼어요.",
