    psych: "기쁜 일을 함께 나누고 싶은 마음, 정성으로 복을 빚고 싶은 바람이 떡의 모습으로 떠오른 거예요.",
    advice: "푸짐한 떡·나눠 먹는 꿈이면 경사·인복의 길조예요. 쉰 떡 꿈이면 다 된 일의 마무리를 챙기세요.",
    folk: "예부터 떡을 푸짐하게 얻거나 나누는 꿈은 경사가 난다고 하여 반겼고, 시루떡 꿈은 집안에 좋은 일이 든다고 했어요.",
    aliases: ["떡", "시루떡", "인절미", "송편", "떡먹는", "잔치떡"], related: ["rice", "meat", "wedding"],
