    psych: "몸이나 마음이 지쳐 돌봄과 회복을 바라는 마음, 점검하고 싶은 욕구가 병원의 모습으로 떠오른 거예요.",
    advice: "치료받고 나은 꿈이면 회복·도움의 길조예요. 헤매거나 나쁜 결과 꿈이면 충분히 쉬며 몸과 마음을 챙기세요.",
    folk: "예부터 병이 낫는 꿈은 묵은 액이 풀린다고 하여 반겼고, 좋은 의원을 만나는 꿈은 귀인이 든다고 했어요.",
    aliases: ["병원", "의사", "치료", "입원", "수술", "퇴원", "간호"], related: ["death", "cry", "tooth"],
