    advice: "좋은 새 옷·갈아입은 꿈이면 새 출발·신분 상승의 길조예요. 낡거나 더럽거나 벗겨진 꿈이면 체면과 처신을 점검하세요.",
    folk: "예부터 좋은 새 옷을 입는 꿈은 벼슬·혼처가 든다고 반겼고, 옷이 벗겨지는 꿈은 체면을 살피라고 했어요.",
    aliases: ["옷", "새옷", "정장", "예복", "옷벗는", "옷장", "옷선물"], related: ["shoes", "mirror", "wedding"],
