/** 카테고리(주제) 목록 — 브라우즈 필터용 */
export const DREAM_CATEGORIES: DreamCategory[] = ["재물", "길몽", "애정", "변화", "주의"];

// 전역 유사어 정규화(별칭으로 못 잡는 흔한 변형 보강)
const SYNONYMS: Record<string, string> = {
  베이비: "아기", 갓난아기: "아기", 멍멍이: "개", 강아지: "개", 고냥이: "고양이", 야옹이: "고양이",
  구렁이: "뱀", 이무기: "용", 변: "똥", 대변: "똥", 소변: "화장실", 금니: "이빨", 어금니: "이빨",
  돌아가신: "조상", 할머니: "조상", 할아버지: "조상", 장례: "죽는", 결혼식: "결혼", 웨딩: "결혼",
  전남친: "옛 애인", 전여친: "옛 애인", 교통사고: "자동차", 운전: "자동차", 등산: "산", 비행: "하늘",
};
function expandTokens(q: string): string[] {
  const toks = q.split(/\s+/).map((t) => t.trim()).filter(Boolean);
  const out: string[] = [];
  for (const t of toks) {
    out.push(t);
    if (SYNONYMS[t]) out.push(SYNONYMS[t]);
  }
  return out;
}

/**
 * 멀티토큰·별칭·상황별 풀이까지 훑는 검색.
 * "돼지 도망"·"검은 돼지"처럼 두 단어 이상도 OK. 매칭 점수 높은 순으로 정렬.
 */
export function searchDreams(query: string): Dream[] {
  const q = query.trim();
  if (!q) return DREAMS;
  const tokens = expandTokens(q);
  const scored = DREAMS.map((d) => {
    const situationText = d.situations.flatMap((g) => [g.group, ...g.cases.map((c) => c.label)]).join(" ");
    let score = 0;
    let matched = 0;
    for (const t of tokens) {
      if (d.keyword.includes(t)) { score += 5; matched++; }
      else if (d.aliases.some((a) => a.includes(t) || t.includes(a))) { score += 3; matched++; }
      else if (situationText.includes(t)) { score += 2; matched++; }
      else if (d.overview.join(" ").includes(t)) { score += 1; matched++; }
    }
    // 모든 토큰이 매칭되면 가산점(AND 우대)
    if (matched === tokens.length && tokens.length > 1) score += 4;
    return { d, score };
  }).filter((x) => x.score > 0);
  scored.sort((a, b) => b.score - a.score);
  return scored.map((x) => x.d);
}

/** 카테고리 필터 */
export function dreamsByCategory(cat: DreamCategory | "전체"): Dream[] {
  return cat === "전체" ? DREAMS : DREAMS.filter((d) => d.category === cat);
}

export function getDream(id: string): Dream | undefined {
  return DREAMS.find((d) => d.id === id);
}

export interface DreamResult {
  dream: Dream;
  related: Dream[];
  caseCount: number;
  lucky: LuckyNumbers;
}

/** 꿈 → 풀이 + 관련 꿈 + 행운번호(결정론적). 같은 꿈은 항상 같은 번호. */
export function interpretDream(id: string): DreamResult | null {
  const dream = getDream(id);
  if (!dream) return null;
  const seed = hashString(`dream|${id}`);
  const numbers = pickUnique(seed, LOTTO_PICK, LOTTO_MAX);
  const related = dream.related.map((rid) => getDream(rid)).filter((d): d is Dream => !!d);
  const caseCount = dream.situations.reduce((s, g) => s + g.cases.length, 0);
  return {
    dream,
    related,
    caseCount,
    lucky: {
      numbers,
      details: numbers.map((n) => ({ n, meaning: meaningOf(n) })),
      source: `${dream.keyword} 행운번호`,
    },
  };
}
